    // 2. 深度克隆 ActionDescriptor
    function duplicateDesc(src) {
        var dst = new ActionDescriptor();
        for (var i = 0; i < src.count; i++) {
            var key = src.getKey(i);
            var type = src.getType(key);
            switch (type) {
                case DescValueType.BOOLEANTYPE: dst.putBoolean(key, src.getBoolean(key)); break;
                case DescValueType.INTEGERTYPE: dst.putInteger(key, src.getInteger(key)); break;
                case DescValueType.DOUBLETYPE:  dst.putDouble(key, src.getDouble(key)); break;
                case DescValueType.STRINGTYPE:  dst.putString(key, src.getString(key)); break;
                case DescValueType.UNITDOUBLE:  dst.putUnitDouble(key, src.getUnitDoubleType(key), src.getUnitDoubleValue(key)); break;
                case DescValueType.OBJECTTYPE:  dst.putObject(key, src.getObjectType(key), duplicateDesc(src.getObjectValue(key))); break;
                case DescValueType.LISTTYPE:    dst.putList(key, src.getList(key)); break;
                case DescValueType.ENUMERATEDTYPE: dst.putEnumerated(key, src.getEnumerationType(key), src.getEnumerationValue(key)); break;
                case DescValueType.REFERENCETYPE:  dst.putReference(key, src.getReference(key)); break;
                case DescValueType.ALIASTYPE:   dst.putPath(key, src.getPath(key)); break;
                case DescValueType.CLASSTYPE:   dst.putClass(key, src.getClass(key)); break;
            }
        }
        return dst;
    }

    // HEX 与 RGB 互转
    function hexToRgb(hex) {
        hex = hex.replace(/^#/, "");
        if (hex.length === 3) hex = hex[0]+hex[0] + hex[1]+hex[1] + hex[2]+hex[2];
        if (hex.length !== 6) return null;
        var r = parseInt(hex.substring(0, 2), 16);
        var g = parseInt(hex.substring(2, 4), 16);
        var b = parseInt(hex.substring(4, 6), 16);
        return (!isNaN(r) && !isNaN(g) && !isNaN(b)) ? [r, g, b] : null;
    }

    function rgbToHex(r, g, b) {
        function c(v) {
            var h = Math.round(v).toString(16);
            return h.length === 1 ? "0" + h : h;
        }
        return ("#" + c(r) + c(g) + c(b)).toUpperCase();
    }

    // 样式比对
    function stylesMatch(d1, d2) {
        if (!d1 || !d2) return false;

        var f1 = d1.hasKey(stringIDToTypeID("fontPostScriptName")) ? d1.getString(stringIDToTypeID("fontPostScriptName")) : "";
        var f2 = d2.hasKey(stringIDToTypeID("fontPostScriptName")) ? d2.getString(stringIDToTypeID("fontPostScriptName")) : "";
        if (f1 !== f2) return false;

        var hasS1 = d1.hasKey(stringIDToTypeID("size"));
        var hasS2 = d2.hasKey(stringIDToTypeID("size"));
        if (hasS1 !== hasS2) return false;
        if (hasS1) {
            if (d1.getUnitDoubleType(stringIDToTypeID("size")) !== d2.getUnitDoubleType(stringIDToTypeID("size"))) return false;
            if (Math.abs(d1.getUnitDoubleValue(stringIDToTypeID("size")) - d2.getUnitDoubleValue(stringIDToTypeID("size"))) > 0.001) return false;
        }

        var hasB1 = d1.hasKey(stringIDToTypeID("baselineShift"));
        var hasB2 = d2.hasKey(stringIDToTypeID("baselineShift"));
        if (hasB1 !== hasB2) return false;
        if (hasB1 && Math.abs(d1.getUnitDoubleValue(stringIDToTypeID("baselineShift")) - d2.getUnitDoubleValue(stringIDToTypeID("baselineShift"))) > 0.001) return false;

        var hasT1 = d1.hasKey(stringIDToTypeID("tracking"));
        var hasT2 = d2.hasKey(stringIDToTypeID("tracking"));
        if (hasT1 !== hasT2) return false;
        if (hasT1 && d1.getInteger(stringIDToTypeID("tracking")) !== d2.getInteger(stringIDToTypeID("tracking"))) return false;

        var hasC1 = d1.hasKey(charIDToTypeID("Clr "));
        var hasC2 = d2.hasKey(charIDToTypeID("Clr "));
        if (hasC1 !== hasC2) return false;
        if (hasC1) {
            var c1 = d1.getObjectValue(charIDToTypeID("Clr "));
            var c2 = d2.getObjectValue(charIDToTypeID("Clr "));
            if (Math.abs(c1.getDouble(charIDToTypeID("Rd  ")) - c2.getDouble(charIDToTypeID("Rd  "))) > 0.1) return false;
            if (Math.abs(c1.getDouble(charIDToTypeID("Grn ")) - c2.getDouble(charIDToTypeID("Grn "))) > 0.1) return false;
            if (Math.abs(c1.getDouble(charIDToTypeID("Bl  ")) - c2.getDouble(charIDToTypeID("Bl  "))) > 0.1) return false;
