    var cfgTargetColor = chkTarget.value ? resolveColor(ddlTargetColor.selection.index, txtTargetHex.text) : null;

    var cfgBaseFont = chkBase.value ? txtBaseFont.text : null;
    var cfgBaseSize = (chkBase.value && chkBaseSize.value) ? parseFloat(txtBaseSize.text) : null;
    var cfgBaseColor = chkBase.value ? resolveColor(ddlBaseColor.selection.index, txtBaseHex.text) : null;

    // 7. 处理单个图层
    function processLayer(layerInfo) {
        selectSingleLayerById(layerInfo.id);

        var ref = new ActionReference();
        ref.putIdentifier(charIDToTypeID("Lyr "), layerInfo.id);
        var layerDesc = executeActionGet(ref);

        if (!layerDesc.hasKey(stringIDToTypeID("textKey"))) return;
        var textDesc = layerDesc.getObjectValue(stringIDToTypeID("textKey"));
        var rawText = textDesc.getString(charIDToTypeID("Txt "));
        if (!rawText || rawText.length === 0) return;

        var origRangesList = null;
        if (textDesc.hasKey(stringIDToTypeID("textStyleRange"))) {
            origRangesList = textDesc.getList(stringIDToTypeID("textStyleRange"));
        }

        function getOriginalStyleAt(idx) {
            if (origRangesList && origRangesList.count > 0) {
                for (var r = 0; r < origRangesList.count; r++) {
                    var rObj = origRangesList.getObjectValue(r);
                    var rf = rObj.hasKey(stringIDToTypeID("from")) ? rObj.getInteger(stringIDToTypeID("from")) : 0;
                    var rt = rObj.hasKey(stringIDToTypeID("to")) ? rObj.getInteger(stringIDToTypeID("to")) : rawText.length;
                    if (idx >= rf && idx < rt) {
                        return rObj.getObjectValue(stringIDToTypeID("textStyle"));
                    }
                }
                return origRangesList.getObjectValue(0).getObjectValue(stringIDToTypeID("textStyle"));
            }
            if (textDesc.hasKey(stringIDToTypeID("defaultStyle"))) {
                return textDesc.getObjectValue(stringIDToTypeID("defaultStyle"));
            }
            return new ActionDescriptor();
        }

        // 使用正则对全部字符进行标记
        var isMatch = [];
        for (var c = 0; c < rawText.length; c++) isMatch.push(false);

        var m;
        userRegex.lastIndex = 0;
        while ((m = userRegex.exec(rawText)) !== null) {
            if (m[0].length === 0) {
                userRegex.lastIndex++;
                continue;
            }
            for (var p = m.index; p < m.index + m[0].length; p++) {
                if (p < isMatch.length) isMatch[p] = true;
            }
        }

        var ranges = [];
        var activeRangeStyle = null;
        var rangeStart = 0;

        for (var i = 0; i < rawText.length; i++) {
            var curStyle = duplicateDesc(getOriginalStyleAt(i));

            if (isMatch[i]) {
                if (chkTarget.value) {
                    if (cfgTargetFont && cfgTargetFont !== "") {
                        curStyle.putString(stringIDToTypeID("fontPostScriptName"), cfgTargetFont);
                        curStyle.putString(stringIDToTypeID("fontName"), cfgTargetFont);
                    }
                    if (chkTargetSize.value && cfgTargetSize && cfgTargetSize > 0) {
                        curStyle.putUnitDouble(stringIDToTypeID("size"), charIDToTypeID("#Pnt"), cfgTargetSize);
                    }
                    if (chkTargetShift.value && cfgTargetShift !== null && !isNaN(cfgTargetShift)) {
                        curStyle.putUnitDouble(stringIDToTypeID("baselineShift"), charIDToTypeID("#Pnt"), cfgTargetShift);
                    }
                    if (chkTargetTrack.value && cfgTargetTrack !== null && !isNaN(cfgTargetTrack)) {
                        curStyle.putInteger(stringIDToTypeID("tracking"), cfgTargetTrack);
                    }
                    if (cfgTargetColor) {
                        var cTarget = new ActionDescriptor();
                        cTarget.putDouble(charIDToTypeID("Rd  "), cfgTargetColor[0]);
                        cTarget.putDouble(charIDToTypeID("Grn "), cfgTargetColor[1]);
                        cTarget.putDouble(charIDToTypeID("Bl  "), cfgTargetColor[2]);
                        curStyle.putObject(charIDToTypeID("Clr "), charIDToTypeID("RGBC"), cTarget);
                    }
                }
            } else {
                if (chkBase.value) {
                    if (cfgBaseFont && cfgBaseFont !== "") {
                        curStyle.putString(stringIDToTypeID("fontPostScriptName"), cfgBaseFont);
                        curStyle.putString(stringIDToTypeID("fontName"), cfgBaseFont);
                    }
                    if (chkBaseSize.value && cfgBaseSize && cfgBaseSize > 0) {
                        curStyle.putUnitDouble(stringIDToTypeID("size"), charIDToTypeID("#Pnt"), cfgBaseSize);
                    }
                    if (cfgBaseColor) {
                        var cBase = new ActionDescriptor();
                        cBase.putDouble(charIDToTypeID("Rd  "), cfgBaseColor[0]);
                        cBase.putDouble(charIDToTypeID("Grn "), cfgBaseColor[1]);
                        cBase.putDouble(charIDToTypeID("Bl  "), cfgBaseColor[2]);
                        curStyle.putObject(charIDToTypeID("Clr "), charIDToTypeID("RGBC"), cBase);
                    }
                }
            }

            if (activeRangeStyle === null) {
                activeRangeStyle = curStyle;
                rangeStart = i;
            } else if (!stylesMatch(activeRangeStyle, curStyle)) {
                ranges.push({
                    from: rangeStart,
                    to: i,
                    style: activeRangeStyle
                });
                activeRangeStyle = curStyle;
                rangeStart = i;
            }
        }

        if (activeRangeStyle !== null) {
            ranges.push({
                from: rangeStart,
                to: rawText.length,
                style: activeRangeStyle
            });
        }

        var styleList = new ActionList();
        for (var k = 0; k < ranges.length; k++) {
            var rItem = ranges[k];
            var rangeDesc = new ActionDescriptor();
            rangeDesc.putInteger(stringIDToTypeID("from"), rItem.from);
            rangeDesc.putInteger(stringIDToTypeID("to"), rItem.to);
            rangeDesc.putObject(stringIDToTypeID("textStyle"), stringIDToTypeID("textStyle"), rItem.style);
            styleList.putObject(stringIDToTypeID("textStyleRange"), rangeDesc);
        }

        textDesc.putList(stringIDToTypeID("textStyleRange"), styleList);

        var idsetd = charIDToTypeID("setd");
        var setDesc = new ActionDescriptor();
        var refT = new ActionReference();
        refT.putEnumerated(charIDToTypeID("TxLr"), charIDToTypeID("Ordn"), charIDToTypeID("Trgt"));
        setDesc.putReference(charIDToTypeID("null"), refT);
        setDesc.putObject(charIDToTypeID("T   "), charIDToTypeID("TxLr"), textDesc);
        executeAction(idsetd, setDesc, DialogModes.NO);
    }

    // 8. 单步撤销与批量执行
    var successCount = 0;
    var failMessages = [];

    doc.suspendHistory("批量修改文本样式(正则定制)", "executeAll()");

    function executeAll() {
        for (var n = 0; n < targetLayers.length; n++) {
            try {
                processLayer(targetLayers[n]);
                successCount++;
            } catch (err) {
                failMessages.push("图层 [" + targetLayers[n].name + "]: " + err);
            }
        }
    }

    // 9. 恢复原本的多选选中状态
    try {
        if (targetLayers.length > 0) {
            selectSingleLayerById(targetLayers[0].id);
            for (var m = 1; m < targetLayers.length; m++) {
                var addDesc = new ActionDescriptor();
                var addRef = new ActionReference();
                addRef.putIdentifier(charIDToTypeID("Lyr "), targetLayers[m].id);
                addDesc.putReference(charIDToTypeID("null"), addRef);
                addDesc.putEnumerated(stringIDToTypeID("selectionModifier"), stringIDToTypeID("selectionModifierType"), stringIDToTypeID("addToSelection"));
                addDesc.putBoolean(charIDToTypeID("MkVs"), false);
                executeAction(charIDToTypeID("slct"), addDesc, DialogModes.NO);
            }
        }
    } catch (e) {}

    // 10. 错误提示
    if (failMessages.length > 0) {
        alert("部分图层修改失败：\n" + failMessages.join("\n"));
    }
})();

